target.css:
:root {
  --ink: #17343b;
  --paper: #fffdf6;
  --pine: #236b63;
  --sky: #ccebef;
  --sun: #f4b942;
  --coral: #e4674e;
  --line: #b9d5d2;
  --muted: #638287;
}

.pass {
  box-sizing: border-box;
  width: 500px;
  min-height: 244px;
  padding: 15px 16px 13px;
  border: 2px solid var(--ink);
  border-radius: 18px 18px 8px 8px;
  background: var(--paper);
  color: var(--ink);
}

.pass-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 11px;
  border-bottom: 2px solid var(--ink);
}

.route p {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.route h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.6px;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--coral);
  color: var(--paper);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.8px;
}

.main-grid {
  display: grid;
  grid-template-columns: 104px 1fr 67px;
  gap: 12px;
  padding: 12px 0;
  align-items: stretch;
}

.platform {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 10px;
  border-radius: 12px;
  background: var(--sky);
}

.tram {
  font-size: 27px;
  line-height: 1;
}

.platform figcaption {
  color: var(--pine);
  font-size: 9px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: 0.7px;
}

.platform b {
  font-size: 24px;
  line-height: 0.9;
}

.timing {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.time-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.time-row span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.time-row strong {
  color: var(--pine);
  font-size: 24px;
  line-height: 1;
  letter-spacing: -0.8px;
}

.progress {
  height: 7px;
  margin: 8px 0 5px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--line);
}

.progress span {
  display: block;
  width: 72%;
  height: 100%;
  border-radius: inherit;
  background: var(--sun);
}

.gate {
  margin: 0;
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
}

.seat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--pine);
  border-radius: 10px;
  background: var(--paper);
}

.seat span,
.seat small {
  color: var(--muted);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.8px;
}

.seat strong {
  color: var(--pine);
  font-size: 28px;
  line-height: 1;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 2px solid var(--ink);
}

.details {
  display: flex;
  gap: 17px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.details li {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.details span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.7px;
}

.details b {
  font-size: 11px;
  line-height: 1;
}

.board {
  width: 45px;
  height: 39px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: var(--pine);
  color: var(--paper);
  font-size: 9px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: 0.5px;
}

